"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Meta } from "@/components/ui/typography";
import { useReducedMotion } from "@/lib/sahajiv-motion/use-reduced-motion";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings } from "@/lib/sahajiv-motion/settings";

export type MarqueeDirection = "left" | "right";
export type MarqueeSpeed = "slow" | "normal" | "fast";
export type MarqueeProps = React.ComponentProps<"section"> & {
  direction?: MarqueeDirection;
  speed?: MarqueeSpeed;
  label?: string;
  paused?: boolean;
  defaultPaused?: boolean;
  onPausedChange?: (paused: boolean) => void;
};

function subscribeVisibility(listener: () => void) {
  document.addEventListener("visibilitychange", listener);
  return () => document.removeEventListener("visibilitychange", listener);
}
const visibleSnapshot = () => document.visibilityState === "visible";
const hiddenSnapshot = () => false;

/** One semantic list; its inert visual copy has no React effects or duplicate IDs. */
export function Marquee({
  children,
  direction = "left",
  speed = "slow",
  label = "Highlights",
  paused,
  defaultPaused = false,
  onPausedChange,
  className,
  ref,
  onPointerEnter,
  onPointerLeave,
  onFocusCapture,
  onBlurCapture,
  ...props
}: MarqueeProps) {
  const root = React.useRef<HTMLElement>(null);
  const viewport = React.useRef<HTMLDivElement>(null);
  const source = React.useRef<HTMLUListElement>(null);
  const copy = React.useRef<HTMLUListElement>(null);
  const [inView, setInView] = React.useState(false);
  const [localPaused, setLocalPaused] = React.useState(defaultPaused);
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const [contentFocused, setContentFocused] = React.useState(false);
  const id = React.useId();
  const manuallyPaused = paused ?? localPaused;
  const visible = React.useSyncExternalStore(subscribeVisibility, visibleSnapshot, hiddenSnapshot);
  const { motion } = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const reduced = useReducedMotion();
  const quiet = reduced || motion.mode === "off";
  const running = inView && visible && !quiet && !manuallyPaused && !hovered && !focused;

  React.useEffect(() => {
    const element = root.current;
    if (!element) return;
    const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const list = source.current, duplicate = copy.current, windowElement = viewport.current, element = root.current;
    if (!list || !duplicate || !windowElement || !element) return;
    const mirror = () => {
      const nodes = Array.from(list.children, (child) => child.cloneNode(true) as HTMLElement);
      for (const node of nodes) {
        for (const part of [node, ...node.querySelectorAll<HTMLElement>("*")]) {
          for (const attribute of ["id", "name", "for", "form", "aria-labelledby", "aria-describedby", "aria-controls", "aria-owns"]) part.removeAttribute(attribute);
          if (part.matches("a,button,input,select,textarea,[tabindex],[contenteditable]")) part.tabIndex = -1;
        }
      }
      duplicate.replaceChildren(...nodes);
      element.dataset.ready = "true";
    };
    const measure = () => element.style.setProperty("--marquee-viewport", `${windowElement.clientWidth}px`);
    mirror();
    measure();
    // Text/content changes matter; per-frame SVG geometry attributes do not.
    const mutation = new MutationObserver(mirror);
    mutation.observe(list, { childList: true, characterData: true, subtree: true });
    const resize = new ResizeObserver(measure);
    resize.observe(windowElement);
    return () => { mutation.disconnect(); resize.disconnect(); duplicate.replaceChildren(); delete element.dataset.ready; };
  }, [children]);

  const status = reduced ? "Reduced motion" : motion.mode === "off" ? "Motion is off" : manuallyPaused ? "Paused" : focused ? "Paused while focused" : hovered ? "Paused while hovered" : running ? "Moving" : "Paused";
  return (
    <section
      {...props}
      ref={(element) => {
        root.current = element;
        if (typeof ref === "function") return ref(element);
        if (ref) ref.current = element;
      }}
      data-slot="marquee"
      data-direction={direction}
      data-speed={speed}
      data-motion={quiet ? "static" : running ? "running" : "paused"}
      data-content-focused={contentFocused || undefined}
      aria-labelledby={props["aria-labelledby"] ?? (props["aria-label"] ? undefined : `${id}-label`)}
      className={cn("v-marquee", className)}
      onPointerEnter={(event) => { onPointerEnter?.(event); if (event.pointerType !== "touch") setHovered(true); }}
      onPointerLeave={(event) => { onPointerLeave?.(event); setHovered(false); }}
      onFocusCapture={(event) => { onFocusCapture?.(event); setFocused(true); setContentFocused(!!source.current?.contains(event.target)); }}
      onBlurCapture={(event) => {
        onBlurCapture?.(event);
        const next = event.relatedTarget;
        setFocused(next instanceof Node && event.currentTarget.contains(next));
        setContentFocused(next instanceof Node && !!source.current?.contains(next));
      }}
    >
      <div data-slot="marquee-header">
        <Meta as="span" id={`${id}-label`}>{label}</Meta>
        <div data-slot="marquee-controls">
          <Meta as="span" data-slot="marquee-status" role="status">{status}</Meta>
          <Button
            size="sm"
            variant="ghost"
            disabled={quiet}
            aria-controls={`${id}-viewport`}
            onClick={() => {
              if (paused === undefined) setLocalPaused(!manuallyPaused);
              onPausedChange?.(!manuallyPaused);
            }}
          >
            {quiet ? "Motion paused" : manuallyPaused ? "Resume motion" : "Pause motion"}
          </Button>
        </div>
      </div>
      <div ref={viewport} data-slot="marquee-viewport" id={`${id}-viewport`}>
        <div data-slot="marquee-track">
          <ul ref={source} data-slot="marquee-content">
            {React.Children.toArray(children).map((child, index) => <li key={React.isValidElement(child) ? child.key ?? index : index}>{child}</li>)}
          </ul>
          <ul ref={copy} data-slot="marquee-copy" aria-hidden="true" inert />
        </div>
      </div>
    </section>
  );
}

@layer sahajiv-states {
[data-slot="marquee"] {
  --marquee-duration: 44s;
  --marquee-gap: var(--s-4);
  display: grid;
  gap: var(--s-4);
  min-inline-size: 0;
  color: var(--v-text);
}
[data-slot="marquee"][data-speed="normal"] { --marquee-duration: 30s; }
[data-slot="marquee"][data-speed="fast"] { --marquee-duration: 18s; }
[data-slot="marquee-header"], [data-slot="marquee-controls"] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s-3);
  min-inline-size: 0;
}
[data-slot="marquee-header"] { justify-content: space-between; }
[data-slot="marquee-controls"] { margin-inline-start: auto; }
[data-slot="marquee-status"] {
  display: grid;
  align-items: center;
  inline-size: 18ch;
  min-block-size: 2lh;
  text-align: end;
}
[data-slot="marquee-viewport"] {
  min-inline-size: 0;
  overflow: hidden;
  padding-block: var(--s-2);
}
[data-slot="marquee-track"] {
  display: flex;
  direction: ltr;
  inline-size: max-content;
}
[data-slot="marquee-content"], [data-slot="marquee-copy"] {
  display: flex;
  flex-shrink: 0;
  align-items: stretch;
  gap: var(--marquee-gap);
  min-inline-size: var(--marquee-viewport, 0px);
  margin: 0;
  padding: 0 var(--marquee-gap) 0 0;
  list-style: none;
}
[data-slot="marquee"] :is([data-slot="marquee-content"], [data-slot="marquee-copy"]) > li {
  flex: 0 0 auto;
  min-inline-size: 0;
  max-inline-size: min(80vw, 30rem);
  overflow-wrap: anywhere;
}
[data-slot="marquee-copy"] { pointer-events: none; }
[data-slot="marquee"][data-ready="true"] [data-slot="marquee-track"] {
  animation: v-marquee-travel var(--marquee-duration) linear infinite;
  animation-play-state: paused;
}
[data-slot="marquee"][data-motion="running"] [data-slot="marquee-track"] { animation-play-state: running; }
[data-slot="marquee"][data-direction="right"] [data-slot="marquee-track"] { animation-direction: reverse; }
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-track"] {
  animation: none;
  inline-size: 100%;
}
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-content"] {
  flex-wrap: wrap;
  min-inline-size: 0;
  inline-size: 100%;
  padding: 0;
}
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-content"] > li { max-inline-size: 100%; }
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-content"] > li > * { max-inline-size: 100%; }
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-viewport"] { overflow: visible; }
[data-slot="marquee"]:is([data-motion="static"], [data-content-focused="true"], :not([data-ready="true"])) [data-slot="marquee-copy"] { display: none; }
@media (prefers-reduced-motion: reduce) {
  [data-slot="marquee"] [data-slot="marquee-track"] { animation: none; inline-size: 100%; }
  [data-slot="marquee"] [data-slot="marquee-content"] { flex-wrap: wrap; min-inline-size: 0; inline-size: 100%; padding: 0; }
  [data-slot="marquee"] [data-slot="marquee-content"] > li { max-inline-size: 100%; }
  [data-slot="marquee"] [data-slot="marquee-content"] > li > * { max-inline-size: 100%; }
  [data-slot="marquee"] [data-slot="marquee-viewport"] { overflow: visible; }
  [data-slot="marquee"] [data-slot="marquee-copy"] { display: none; }
}
@keyframes v-marquee-travel { to { transform: translate3d(-50%, 0, 0); } }

}
